/* Finite State Machine (FSM) for Alarm System */
states {
    Normal;
    MediumAlarm;
    HighAlarm;
    Paused;
}

events {
    NoBreathDetected;
    BreathRateExceeded;
    AudioPausePressed;
    ApneaTimeIntervalExpired;
    LowPressureDetected;
}

transitions {
    Normal --> MediumAlarm : NoBreathDetected [guard: true];
    Normal --> HighAlarm : BreathRateExceeded [guard: true];
    Normal --> Paused : AudioPausePressed [guard: true];
    MediumAlarm --> Normal : ApneaTimeIntervalExpired [guard: true];
    HighAlarm --> Normal : ApneaTimeIntervalExpired [guard: true];
    Paused --> Normal : /* after 60 seconds */ [guard: true];
}

/* Guards and Actions */
guard NoBreathDetected {
    /* Check if no breath is triggered within apnea time interval */
    return true; // Assume apnea condition met
}
guard BreathRateExceeded {
    /* Check if breath rate exceeds setting */
    return true; // Assume rate exceeds
}
guard AudioPausePressed {
    /* Inhibit all active alarms */
    return true; // Assume pause initiated
}
guard ApneaTimeIntervalExpired {
    /* Allow transition back to Normal */
    return true; // Assume interval expired
}

actions {
    MediumAlarm: {
        /* Yellow color, flashing 0.5Hz, 50% duty cycle */
        setAlarmColor("yellow");
        startFlashing(0.5, 0.5);
        displayText("APNEA ALARM");
    }
    HighAlarm: {
        /* Auditory signal: 10 pulses, 200ms each, 500Hz */
        playAuditorySignal(10, 200, 500);
        displayText("HIGH BREATH RATE"); // For breath rate alarm
        displayText("LOW INSP P"); // For low pressure alarm
    }
    Paused: {
        /* Display IEC 60417-5576 symbol */
        displayAlarmSymbol("IEC 60417-5576");
        pauseAllAlarms(60); // 60 seconds pause
    }
}

